policies.statement:
// 02 Defence in depth for "the agent never records a disposition". The engine's Cedar schema is generated from
// the Gateway's tool manifest, so a policy cannot even name a tool that does not exist (a forbid on
// surv___record_disposition is rejected at creation: "unrecognized action"). What CAN be written is the
// closed list: any action outside the twelve known tools is forbidden for everyone. If a record_disposition
// tool is ever added to the target, it is denied until someone edits this list on purpose.
// The resource must be the specific Gateway ARN: with `resource is AgentCore::Gateway` the validator does not bind
// the Gateway's tool manifest and rejects every tool name as unrecognized (observed 2026-11-04).
forbid (
  principal,
  action,
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:eu-west-2:384308066035:gateway/surv-default-surv-investigator-gsq1ismkrw"
)
unless {
  action in [
    AgentCore::Action::"surv___get_alert",
    AgentCore::Action::"surv___get_procedures",
    AgentCore::Action::"surv___recall_memory",
    AgentCore::Action::"surv___get_order_events",
    AgentCore::Action::"surv___reconstruct_book",
    AgentCore::Action::"surv___compute_discriminators",
    AgentCore::Action::"surv___get_trader_profile",
    AgentCore::Action::"surv___get_trader_alert_history",
    AgentCore::Action::"surv___get_market_events",
    AgentCore::Action::"surv___get_instrument_stats",
    AgentCore::Action::"surv___propose_disposition",
    AgentCore::Action::"surv___draft_stor_narrative"
  ]
};

// 03a Evidence before proposal (1 of 2): a proposal is permitted only after the alert was read, its order
// events pulled and its discriminators computed in this session, and each of those calls RETURNED this
// alert's id. The match is on the answer (output.alert_id), not on the request: a tool that answers with an
// error returns no alert id, so a failed lookup does not count. Three temporal operators is the per-policy
// maximum, hence the split with 03b.
permit (
  principal is AgentCore::OAuthUser,
  action == AgentCore::Action::"surv___propose_disposition",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:eu-west-2:384308066035:gateway/surv-default-surv-investigator-gsq1ismkrw"
)
when temporal {
  formerly within 2h AgentCore::Action::"surv___get_alert"::response{
    eventResource: resource,
    output.alert_id: context.input.alert_id
  }
  && formerly within 2h AgentCore::Action::"surv___get_order_events"::response{
    eventResource: resource,
    output.alert_id: context.input.alert_id
  }
  && formerly within 2h AgentCore::Action::"surv___compute_discriminators"::response{
    eventResource: resource,
    output.alert_id: context.input.alert_id
  }
};

// 03b Evidence before proposal (2 of 2): the trader's profile and the market events must have been RETURNED
// for this alert in the session (output.alert_id). The profile tool answers with the alert's id only for the
// alert's own trader, the market tool only for the alert's own instrument and window; an answer that is an
// error carries none. A forbid-unless cannot be overridden by any permit.
forbid (
  principal,
  action == AgentCore::Action::"surv___propose_disposition",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:eu-west-2:384308066035:gateway/surv-default-surv-investigator-gsq1ismkrw"
)
unless temporal {
  formerly within 2h AgentCore::Action::"surv___get_trader_profile"::response{
    eventResource: resource,
    output.alert_id: context.input.alert_id
  }
  && formerly within 2h AgentCore::Action::"surv___get_market_events"::response{
    eventResource: resource,
    output.alert_id: context.input.alert_id
  }
};

// 04 A false-positive closure additionally needs the trader's alert history RETURNED for this alert in the
// session (output.alert_id; prior dispositions are context the closure standard requires the analyst to have
// seen). A history call that failed, or one for another alert or another trader, does not count.
forbid (
  principal,
  action == AgentCore::Action::"surv___propose_disposition",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:eu-west-2:384308066035:gateway/surv-default-surv-investigator-gsq1ismkrw"
)
when { context.input.disposition == "CLOSE_FP" }
unless temporal {
  formerly within 2h AgentCore::Action::"surv___get_trader_alert_history"::response{
    eventResource: resource,
    output.alert_id: context.input.alert_id
  }
};

// 05 A STOR narrative may be drafted only after a DRAFT_STOR proposal for the same alert completed.
// Correlates on the proposal's INPUT (what was proposed), which exists whether or not outputs are declared.
permit (
  principal is AgentCore::OAuthUser,
  action == AgentCore::Action::"surv___draft_stor_narrative",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:eu-west-2:384308066035:gateway/surv-default-surv-investigator-gsq1ismkrw"
)
when temporal {
  formerly within 2h AgentCore::Action::"surv___propose_disposition"::response{
    eventResource: resource,
    input.alert_id: context.input.alert_id,
    input.disposition: "DRAFT_STOR"
  }
};

// 06 One proposal per alert per session. Matching ::response is what makes the self-reference safe: the
// request being authorised has no response yet, so the first proposal does not forbid itself.
forbid (
  principal,
  action == AgentCore::Action::"surv___propose_disposition",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:eu-west-2:384308066035:gateway/surv-default-surv-investigator-gsq1ismkrw"
)
when temporal {
  formerly within 24h AgentCore::Action::"surv___propose_disposition"::response{
    eventResource: resource,
    input.alert_id: context.input.alert_id
  }
};

// 07 Only Level-2 analysts may draft a STOR. JWT claims arrive as string tags; the Cognito groups claim is
// an array, so it reaches Cedar as the text ["L2"] and is matched with `like`.
forbid (
  principal is AgentCore::OAuthUser,
  action == AgentCore::Action::"surv___draft_stor_narrative",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:eu-west-2:384308066035:gateway/surv-default-surv-investigator-gsq1ismkrw"
)
unless {
  principal.hasTag("cognito:groups") && principal.getTag("cognito:groups") like "*L2*"
};

// 08 Bound cost and loops: at most 6 order-event pulls per session. `count` includes the current request,
// so the seventh call in the window is the first one denied. Behaviour shaping, not a security boundary:
// the caller names the session.
forbid (
  principal,
  action == AgentCore::Action::"surv___get_order_events",
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:eu-west-2:384308066035:gateway/surv-default-surv-investigator-gsq1ismkrw"
)
when temporal {
  exists (n: Long).
    (count for (t: Timepoint).
      where (formerly within 2h (AgentCore::Action::"surv___get_order_events"::request{ eventResource: resource } && tp(t)))) == n
    && n > 6
};
